"""Dashboard generator."""
from __future__ import annotations
import json
from pathlib import Path
from .tamper_simulator import run_adversarial_tamper_suite

ROOT = Path(__file__).resolve().parents[3]


def collect_data(work_dir: object) -> object:
    """Collect measured telemetry, attack outcomes and example receipts. Complexity: O(n + W) time and O(n + M) space; n is traversed data, W delegated work, M retained delegated state."""
    from examples.ghost_native_dependency import run as ghost
    from examples.wal_heisenbug_shrink import run as wal
    from examples.quantum_drift_reroute import run as quantum
    work_dir = Path(work_dir)
    data = {'ghost':ghost(work_dir/'ghost'),'wal':wal(work_dir/'wal'),'quantum':quantum(work_dir/'quantum')}
    for name,file in [('benchmarks','latest_benchmark_metrics.json'),('ffi','rust_ffi_metrics.json'),('invariants','property_fuzzing.json'),('linux','linux_verification.json')]:
        path = ROOT/'benchmarks/results'/file
        data[name] = json.loads(path.read_text()) if path.exists() else {'available':False}
    data['tamper'] = run_adversarial_tamper_suite(data['wal']['bundle'])
    return data


def generate_dashboard(output: object=None,work_dir: object=None) -> object:
    """Render a self-contained dashboard from the measured results. Complexity: O(n + W) time and O(n + M) space; n is traversed data, W delegated work, M retained delegated state."""
    output = Path(output or ROOT/'benchmarks/results/demo_mission_control.html')
    data = collect_data(work_dir or ROOT/'dist/demo')
    payload = json.dumps(data,separators=(',',':'),ensure_ascii=True).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    output.parent.mkdir(parents=True,exist_ok=True)
    output.write_text(HTML.replace('__VK_DATA__',payload),encoding='utf-8')
    return output,data


HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>VeriKernel | Mission control</title>
<style>
:root{color-scheme:dark;--bg:#102430;--panel:#142b38;--line:#35505e;--text:#d8e6ec;--muted:#9db5bf;--blue:#7abfe3;--amber:#e7bb73;--red:#e68b83;--green:#8ac6a5}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.55 'Segoe UI','Trebuchet MS',sans-serif}button,input{font:inherit}button{cursor:pointer;color:var(--text);background:#1d3b4b;border:1px solid var(--line);padding:9px 14px;border-radius:5px}button:hover,button:focus-visible{border-color:var(--blue);background:#294c60}button[aria-selected=true]{border-color:var(--blue);color:var(--blue)}aside{position:fixed;width:240px;inset:0 auto 0 0;padding:34px 22px;border-right:1px solid var(--line);background:#11212c}aside h1{font:30px Georgia,serif;margin:0}aside p{font-size:13px;color:var(--muted)}nav{display:grid;gap:10px;margin-top:40px}nav button{text-align:left;padding:13px;background:transparent}aside footer{position:absolute;bottom:24px;font-size:12px;color:var(--muted);max-width:190px}main{margin-left:240px;padding:36px 42px;max-width:1600px}header{display:flex;gap:20px;align-items:start;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:24px;margin-bottom:28px}header h2{font:38px Georgia,serif;margin:0 0 10px}header p{margin:0;color:var(--muted);max-width:650px}.mode{color:var(--amber);font-size:13px;white-space:nowrap}.view[hidden]{display:none}.columns{display:grid;grid-template-columns:1.3fr 1fr;gap:32px}.panel{padding:22px;background:var(--panel);border:1px solid var(--line);border-radius:8px;margin-bottom:24px}h3{font:25px Georgia,serif;margin:0 0 16px}h4{font-size:16px;margin:16px 0 8px}p{max-width:78ch}.muted,small{color:var(--muted)}.number{font:40px Georgia,serif;color:var(--blue)}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;border-bottom:1px solid var(--line);padding:11px 8px}th{font-weight:500;color:var(--muted)}td:last-child{color:var(--blue)}pre{font:12px/1.65 Consolas,monospace;overflow:auto;max-height:360px;white-space:pre-wrap;overflow-wrap:anywhere;padding:14px;background:#0d1e28;border-radius:5px}.wire{display:grid;grid-template-columns:repeat(16,minmax(18px,1fr));gap:4px;max-height:360px;overflow:auto;font:12px/1.8 Consolas,monospace}.wire span{background:#244353;text-align:center;border-radius:2px}.wire span.changed{background:#823e3e;color:#fff}.legend{display:flex;gap:20px;flex-wrap:wrap;font-size:13px;margin:12px 0;color:var(--muted)}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}svg{width:100%;height:auto;min-height:180px}svg text{fill:var(--text);font:13px 'Segoe UI',sans-serif}svg line,svg path{stroke:var(--line);stroke-width:3}svg circle{fill:#203f50;stroke:var(--blue);stroke-width:2}svg .bad{stroke:var(--red);fill:#513637}svg .active{fill:#356481;stroke:var(--blue)}svg g[data-trial],svg g[data-qubit]{cursor:pointer}.bar{height:12px;background:var(--blue);margin:6px 0 14px}.bar.python{background:var(--amber)}.status{color:var(--green);font-size:14px}.attack-buttons button{font-size:13px}input[type=range]{width:100%;accent-color:var(--blue)}.faults{display:grid;grid-template-columns:repeat(16,1fr);gap:5px}.faults span{padding:7px 0;background:#213b49;text-align:center;font-size:12px;border-radius:2px}.faults .selected{background:#704742}.faults .root{outline:2px solid var(--amber)}.root-note{color:var(--amber)}.summary{display:flex;gap:26px;flex-wrap:wrap;align-items:baseline}.summary span{font-size:14px;color:var(--muted)}.error{color:var(--red)}a{color:var(--blue)}@media(max-width:1000px){aside{position:static;width:auto;padding:20px}aside footer{position:static;margin-top:20px}nav{grid-template-columns:repeat(5,1fr);margin-top:20px;gap:5px}nav button{font-size:12px;padding:8px}main{margin:0;padding:24px}.columns{grid-template-columns:1fr}header{display:block}.mode{margin-top:12px}}@media(prefers-reduced-motion:no-preference){button{transition:background .12s}}
</style></head><body>
<aside><h1>VeriKernel</h1><p>Execution evidence · v0.2</p><nav aria-label="Inspection views" role="tablist">
<button role="tab" aria-selected="true" data-view="telemetry">Telemetry</button><button role="tab" aria-selected="false" data-view="ghost">Ghost dependencies</button><button role="tab" aria-selected="false" data-view="shrink">Fault shrinker</button><button role="tab" aria-selected="false" data-view="tamper">Tamper lab</button><button role="tab" aria-selected="false" data-view="quantum">Quantum routing</button>
</nav><footer>Inspect actual recorded runs. Live cryptographic checks use the local server.<br><button id="export">Export evidence</button></footer></aside>
<main><header><div><h2>Inspect the boundary.</h2><p>A dependency contract, a reproducible fault, and a sealed execution stream. Follow the evidence from a syscall boundary to its signed root.</p></div><div class="mode" id="mode">Standalone recorded evidence</div></header>
<section class="view" id="telemetry" role="tabpanel"><div class="columns"><div><h3>One event. 128 bytes.</h3><p class="muted">The producer authenticates the event before the consumer signs its Merkle epoch. The strip below is a real event from the WAL counterexample.</p><div class="panel"><div class="wire" id="event-wire"></div><div class="legend"><span>0–31: sequence, clock, operation</span><span>32–63: inode and stack</span><span>64–127: target and ratchet</span></div></div><h3>Transport under burst load</h3><table id="transport"><thead><tr><th>Measured transport</th><th>Drop rate</th><th>Inversions</th><th>p99 μs</th></tr></thead><tbody></tbody></table><p class="muted">10,000 inputs. Suppressed duplicate observations are counted separately from capacity loss. This is a controlled portable workload, not a kernel throughput claim.</p></div><div><div class="panel"><h3>Native arithmetic bridge</h3><div class="summary"><strong class="number" id="ffi-speed"></strong><span>FNV-1a speedup</span></div><div id="ffi-bars"></div><small>Actual 1,024-byte calls. Scalar FFI overhead can outweigh arithmetic savings.</small></div><div class="panel"><h3>Verification ledger</h3><table id="ledger"></table></div><div class="panel"><h3>Signature amortization</h3><table id="signatures"></table></div></div></div></section>
<section class="view" id="ghost" role="tabpanel" hidden><div class="columns"><div><h3>What the source did not declare</h3><p>The first run loads a real system library and opens a loopback TCP connection. Select a dependency to inspect its observed contract addition.</p><svg viewBox="0 0 640 310" aria-label="Observed dependency graph"><path d="M110 150 L310 65 M110 150 L310 235 M310 65 L530 150 M310 235 L530 150"/><g id="ghost-native"><circle cx="310" cy="65" r="38" class="bad"/><text x="310" y="70" text-anchor="middle">Library</text></g><g id="ghost-network"><circle cx="310" cy="235" r="38" class="bad"/><text x="310" y="240" text-anchor="middle">Socket</text></g><circle cx="110" cy="150" r="42"/><text x="110" y="155" text-anchor="middle">Workload</text><circle cx="530" cy="150" r="48"/><text x="530" y="155" text-anchor="middle">Contract</text></svg><button id="heal">Inspect healed run</button><p id="heal-state" class="root-note">Audit run: undeclared dependencies observed.</p></div><div><h3>Machine-applicable patch</h3><pre id="patch"></pre><p class="muted" id="ghost-source"></p></div></div></section>
<section class="view" id="shrink" role="tabpanel" hidden><h3>32 faults to two necessary causes</h3><p>Each node is an actual oracle evaluation. Red means the WAL acknowledged a transaction without a durable remote or local commit. Select a trial to inspect its fault mask.</p><div class="columns"><div class="panel"><svg id="shrink-tree" viewBox="0 0 640 400" aria-label="Delta debugging oracle tree"></svg></div><div><div class="actions"><button id="previous">Previous trial</button><button id="next">Next trial</button></div><input type="range" id="trial" min="0" value="0" aria-label="Oracle trial"><p id="trial-label"></p><div class="faults" id="fault-mask"></div><p class="root-note">Site 7: EAGAIN on socket read<br>Site 23: ENOSPC on fallback WAL write</p><pre id="trial-details"></pre></div></div></section>
<section class="view" id="tamper" role="tabpanel" hidden><h3>Change one bit. Inspect the break.</h3><p id="attack-mode">Standalone mode shows recorded cryptographic verification. With the local server, each button runs a fresh attack against the sealed bundle.</p><div class="actions attack-buttons"><button data-attack="payload_bit_flip">Flip event bit</button><button data-attack="mid_epoch_tail_truncation">Truncate epoch tail</button><button data-attack="cross_cpu_sequence_swap">Swap ordered events</button><button data-attack="pqc_signature_lattice_forge">Forge lattice response</button></div><p id="attack-status" class="status" aria-live="polite"></p><div class="columns"><div><h4>Changed wire bytes</h4><div id="attack-wire" class="wire"></div><h4>Exact rejection</h4><pre id="rejection"></pre></div><div><h4>Merkle branch and root comparison</h4><pre id="branch"></pre><small id="attack-source"></small></div></div></section>
<section class="view" id="quantum" role="tabpanel" hidden><div class="columns"><div><h3>Move the circuit away from drift.</h3><p>The modeled q₂ dephasing rate rises 15×. The firewall abstains; the router enumerates healthy embeddings and checks the logical unitary in the new physical basis.</p><div class="actions"><button id="original-layout">Inspect original layout</button><button id="recovered-layout">Inspect recovered layout</button></div><svg id="topology" viewBox="0 0 640 460" aria-label="Quantum calibration topology"></svg></div><div><div class="panel"><h3>Recovery receipt</h3><table id="quantum-scores"></table><p id="layout-proof" class="status"></p></div><h4>Selected qubit calibration</h4><pre id="qubit-info"></pre><p class="muted" id="calibration-source"></p></div></div></section>
</main><script type="application/json" id="evidence">__VK_DATA__</script><script>
'use strict';
const data=JSON.parse(document.getElementById('evidence').textContent), byId=id=>document.getElementById(id), pretty=value=>JSON.stringify(value,null,2);
let live=false, trial=0;
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.view').forEach(view=>view.hidden=view.id!==button.dataset.view);document.querySelectorAll('[data-view]').forEach(tab=>tab.setAttribute('aria-selected',String(tab===button)));}));
function row(table,values){const tr=document.createElement('tr');values.forEach(value=>{const td=document.createElement('td');td.textContent=String(value);tr.appendChild(td);});table.appendChild(tr);}
function wire(id,before,after){const parent=byId(id);parent.replaceChildren();for(let index=0;index<Math.max(before.length,after.length);index+=2){const cell=document.createElement('span'),a=before.slice(index,index+2),b=after.slice(index,index+2);cell.textContent=b||'×';cell.title='Byte '+(index/2)+': '+a+' → '+(b||'removed');if(a!==b)cell.className='changed';parent.appendChild(cell);}}
const sample=data.tamper.attacks.payload_bit_flip.before_hex;wire('event-wire',sample,sample);
const transport=data.benchmarks.transport||{};Object.entries(transport).forEach(([name,value])=>row(byId('transport').querySelector('tbody'),[name,value.drop_rate_percent.toFixed(2)+'%',value.sequence_inversions,value.producer_p99_us.toFixed(2)]));
byId('ffi-speed').textContent=data.ffi.speedup?data.ffi.speedup.toFixed(2)+'×':'Not measured';
if(data.ffi.fnv1a_1024){const values=data.ffi.fnv1a_1024;['python','native'].forEach(name=>{const label=document.createElement('div');label.textContent=name+': '+(values[name].seconds*1000).toFixed(2)+' ms';const bar=document.createElement('div');bar.className='bar '+name;bar.style.width=Math.max(1,100*values[name].seconds/Math.max(values.python.seconds,values.native.seconds))+'%';byId('ffi-bars').append(label,bar);});}
row(byId('ledger'),['Wire format','128 bytes']);row(byId('ledger'),['Invariant seeds',data.invariants.seeds||'Not measured']);row(byId('ledger'),['Ratchet attacks',data.invariants.tamper_detections||'Not measured']);row(byId('ledger'),['WAL replays',data.wal.reproductions+'/'+data.wal.replay_runs]);row(byId('ledger'),['Kernel execution',data.linux.verified?data.linux.execution.backend:'Unavailable']);
Object.entries(data.benchmarks.attestation||{}).forEach(([name,value])=>row(byId('signatures'),[name,value.signature_bytes.toLocaleString()+' bytes']));
byId('patch').textContent=pretty(data.ghost.patch);byId('ghost-source').textContent='Loaded '+data.ghost.library+'; connected to '+data.ghost.endpoint.join(':');
byId('ghost-native').onclick=()=>byId('patch').textContent=pretty({add:{shared_libraries:data.ghost.patch.add.shared_libraries}});byId('ghost-network').onclick=()=>byId('patch').textContent=pretty({add:{network:data.ghost.patch.add.network}});
byId('heal').onclick=()=>{byId('heal-state').textContent=data.ghost.healed?'Recorded strict rerun: library and endpoint accepted.':'Recorded strict rerun rejected the patch.';byId('patch').textContent=pretty(data.ghost.patch);};
const svgNS='http://www.w3.org/2000/svg';function svg(tag,attributes,text){const node=document.createElementNS(svgNS,tag);Object.entries(attributes).forEach(([key,value])=>node.setAttribute(key,String(value)));if(text!==undefined)node.textContent=text;return node;}
const trials=data.wal.oracle_trace;byId('trial').max=trials.length-1;
trials.forEach((value,index)=>{const x=55+(index%8)*76,y=40+Math.floor(index/8)*95;if(value.parent!==null){const px=55+(value.parent%8)*76,py=40+Math.floor(value.parent/8)*95;byId('shrink-tree').appendChild(svg('line',{x1:px,y1:py,x2:x,y2:y}));}const group=svg('g',{'data-trial':index});group.appendChild(svg('circle',{cx:x,cy:y,r:22,class:value.failed?'bad':''}));group.appendChild(svg('text',{x:x,y:y+5,'text-anchor':'middle'},value.sites.length));group.onclick=()=>selectTrial(index);byId('shrink-tree').appendChild(group);});
function selectTrial(index){trial=Math.max(0,Math.min(trials.length-1,index));byId('trial').value=trial;const value=trials[trial];byId('trial-label').textContent='Oracle trial '+(trial+1)+' / '+trials.length+': '+value.sites.length+' faults; '+(value.failed?'durability violation reproduced':'durability violation absent');byId('fault-mask').replaceChildren();for(let site=0;site<32;site++){const node=document.createElement('span');node.textContent=site;node.className=(value.sites.includes(site)?'selected ':'')+(data.wal.minimal_sites.includes(site)?'root':'');byId('fault-mask').appendChild(node);}byId('trial-details').textContent=pretty(value);}
byId('trial').oninput=event=>selectTrial(Number(event.target.value));byId('next').onclick=()=>selectTrial(trial+1);byId('previous').onclick=()=>selectTrial(trial-1);selectTrial(0);
function showAttack(kind,result){byId('attack-status').textContent=kind+': '+(result.detected?'attack rejected':'attack accepted')+(result.first_corrupted_index===null?'':' at stream index '+result.first_corrupted_index);wire('attack-wire',result.before_hex,result.after_hex);byId('rejection').textContent=pretty(result.rejection);byId('branch').textContent=pretty({original_root:result.original_root,altered_root:result.altered_root,branch:result.merkle_branch});byId('attack-source').textContent=data.tamper.cpu_scope;}
document.querySelectorAll('[data-attack]').forEach(button=>button.addEventListener('click',async()=>{const kind=button.dataset.attack;button.disabled=true;try{if(live){const response=await fetch('/api/attack',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:kind})});if(!response.ok)throw new Error('Verification request returned '+response.status);showAttack(kind,await response.json());}else showAttack(kind,data.tamper.attacks[kind]);}catch(error){byId('attack-status').textContent=String(error);byId('attack-status').className='error';}finally{button.disabled=false;}}));showAttack('payload_bit_flip',data.tamper.attacks.payload_bit_flip);
const positions=[[60,160],[160,160],[260,160],[360,160],[460,160],[560,160],[260,260],[260,360],[360,360],[460,360],[160,360],[60,360]];
function topology(layout){const parent=byId('topology');parent.replaceChildren();data.quantum.couplers.forEach(([a,b])=>parent.appendChild(svg('line',{x1:positions[a][0],y1:positions[a][1],x2:positions[b][0],y2:positions[b][1]})));data.quantum.qubits.forEach(q=>{const group=svg('g',{'data-qubit':q}),position=positions[q];group.appendChild(svg('circle',{cx:position[0],cy:position[1],r:25,class:q===2?'bad':layout.includes(q)?'active':''}));group.appendChild(svg('text',{x:position[0],y:position[1]+5,'text-anchor':'middle'},'q'+q));group.onclick=()=>byId('qubit-info').textContent=pretty({qubit:q,calibration:data.quantum.calibration[String(q)]});parent.appendChild(group);});byId('layout-proof').textContent='Layout ['+layout.join(', ')+']; checked unitary fidelity '+data.quantum.reroute.unitary_fidelity.toFixed(9);}
const routing=data.quantum.reroute;row(byId('quantum-scores'),['Before drift',routing.pre_drift_fidelity.toFixed(9)]);row(byId('quantum-scores'),['Drifted layout',routing.drifted_fidelity.toFixed(9)]);row(byId('quantum-scores'),['Recovered layout',routing.recovered_fidelity.toFixed(9)]);row(byId('quantum-scores'),['Healthy embeddings',routing.candidates]);byId('calibration-source').textContent=data.quantum.evidence;byId('qubit-info').textContent=pretty({qubit:2,before_T2_us:data.quantum.q2_t2_before_us,after_T2_us:data.quantum.q2_t2_after_us});byId('original-layout').onclick=()=>topology(routing.original_layout);byId('recovered-layout').onclick=()=>topology(routing.layout);topology(routing.layout);
byId('export').onclick=()=>{const url=URL.createObjectURL(new Blob([pretty(data)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='verikernel-evidence.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
if(location.protocol==='http:'||location.protocol==='https:'){fetch('/api/status').then(response=>{if(!response.ok)throw new Error('Local verification unavailable');return response.json();}).then(status=>{live=status.live_verification===true;byId('mode').textContent=live?'Live local verification':'Recorded evidence';byId('attack-mode').textContent='Each attack button now runs fresh ratchet, Merkle and ML-DSA verification on the local server.';}).catch(()=>byId('mode').textContent='Standalone recorded evidence');}
</script></body></html>'''
